fn count_true(condition: &[bool]) -> usize {
    // Requires that the input slice is non-empty
    // Ensures that the count of true values is non-negative
    // The count of true values is less than or equal to the length of the condition
    requires(condition.len() > 0);
    ensures(|result: usize| result <= condition.len() && result >= 0);
    
    condition.iter().filter(|&&x| x).count()
}

fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // Requires that the lengths of the condition and arr are equal
    requires(condition.len() == arr.len());
    // Ensures that the length of the result is equal to the count of true values in the condition
    ensures(|result: &Vec<f32>| result.len() == count_true(&condition));
    
    // Create a new vector to hold the filtered results
    let mut result = Vec::new();

    // Iterate over the condition and arr simultaneously
    for (c, &value) in condition.iter().zip(arr.iter()) {
        // Invariant: The length of the result is always less than or equal to the number of true values seen so far
        invariant(result.len() <= count_true(&condition));
        
        if *c {
            result.push(value);
        }
    }

    // Verify that the length of the result is equal to the number of true values in the condition
    assert_eq!(result.len(), count_true(&condition), "Result length must match the count of true values");

    result
}

fn main() {
    // Example usage
    let condition = vec![true, false, true, true];
    let arr = vec![1.0, 2.0, 3.0, 4.0];
    
    let filtered = extract(condition, arr);
    println!("{:?}", filtered); // Output: [1.0, 3.0, 4.0]
}